const drawingCanvas=$('icon-canvas'),drawingContext=drawingCanvas.getContext('2d');
let drawingHistory=[],drawingStroke=null,drawingErase=false,drawingCursor={x:7,y:7};
const drawingSize=()=>[8,16,32].includes(Math.sqrt(draft?.drawing?.length))?Math.sqrt(draft.drawing.length):draft?.grid||16;
const blankDrawing=()=> '0'.repeat(drawingSize()**2);
function renderDrawing(){const n=drawingSize(),cell=256/n,ctx=drawingContext,bitmap=draft?.drawing||blankDrawing();ctx.clearRect(0,0,256,256);ctx.fillStyle=draft?.color||'#b9c990';for(let i=0;i<n*n;i++)if(bitmap[i]==='1')ctx.fillRect(i%n*cell,Math.floor(i/n)*cell,cell,cell);ctx.strokeStyle='rgba(160,170,145,.2)';ctx.lineWidth=1;ctx.beginPath();for(let i=0;i<=n;i++){ctx.moveTo(i*cell+.5,0);ctx.lineTo(i*cell+.5,256);ctx.moveTo(0,i*cell+.5);ctx.lineTo(256,i*cell+.5)}ctx.stroke();$('drawing-grid').value=n;$('undo-drawing').disabled=!drawingHistory.length;$('draw-pen').setAttribute('aria-pressed',String(!drawingErase));$('draw-eraser').setAttribute('aria-pressed',String(drawingErase))}
function selectIconMode(mode){const custom=mode==='draw';if(custom){if(draft.icon!=='HandDrawn')draft.libraryIcon=draft.icon;draft.icon='HandDrawn';draft.drawing ||=blankDrawing()}else if(draft.icon==='HandDrawn')draft.icon=draft.libraryIcon||'Folder';$('library-icons').hidden=custom;$('draw-panel').hidden=!custom;$('use-library').setAttribute('aria-pressed',String(!custom));$('draw-own').setAttribute('aria-pressed',String(custom));draftPreview();renderIconPicker();renderDrawing()}
function resetDrawingEditor(){drawingHistory=[];drawingStroke=null;drawingErase=false;selectIconMode(draft.icon==='HandDrawn'?'draw':'library')}
function rememberDrawing(){drawingHistory.push({drawing:draft.drawing,grid:drawingSize()});if(drawingHistory.length>40)drawingHistory.shift()}
$('drawing-grid').onchange=e=>{const before=drawingSize(),n=Number(e.target.value);rememberDrawing();const old=draft.drawing||blankDrawing();draft.grid=n;draft.drawing=Array.from({length:n*n},(_,i)=>old[Math.floor(Math.floor(i/n)*before/n)*before+Math.floor(i%n*before/n)]||'0').join('');drawingCursor={x:Math.min(n-1,drawingCursor.x),y:Math.min(n-1,drawingCursor.y)};draftPreview();renderDrawing()};
$('use-library').onclick=()=>selectIconMode('library');$('draw-own').onclick=()=>selectIconMode('draw');$('draw-pen').onclick=()=>{drawingErase=false;renderDrawing()};$('draw-eraser').onclick=()=>{drawingErase=true;renderDrawing()};$('undo-drawing').onclick=()=>{if(drawingHistory.length){Object.assign(draft,drawingHistory.pop());draftPreview();renderDrawing()}};$('clear-drawing').onclick=()=>{if(draft.drawing?.includes('1')){rememberDrawing();draft.drawing=blankDrawing();draftPreview();renderDrawing()}};
function canvasPoint(e){const r=drawingCanvas.getBoundingClientRect(),n=drawingSize();return{x:Math.max(0,Math.min(n-1,Math.floor((e.clientX-r.left)/r.width*n))),y:Math.max(0,Math.min(n-1,Math.floor((e.clientY-r.top)/r.height*n)))}}
function paintTo(point){const n=drawingSize(),previous=drawingStroke.last||point,steps=Math.max(Math.abs(point.x-previous.x),Math.abs(point.y-previous.y)),pixels=[...draft.drawing];for(let step=0;step<=steps;step++){const t=steps?step/steps:0,x=Math.round(previous.x+(point.x-previous.x)*t),y=Math.round(previous.y+(point.y-previous.y)*t);pixels[y*n+x]=drawingErase?'0':'1'}draft.drawing=pixels.join('');drawingStroke.last=point;draftPreview();renderDrawing()}
drawingCanvas.addEventListener('pointerdown',e=>{if(e.button!==0||drawingStroke)return;e.preventDefault();drawingCanvas.setPointerCapture(e.pointerId);rememberDrawing();drawingStroke={id:e.pointerId,last:null};paintTo(canvasPoint(e))});drawingCanvas.addEventListener('pointermove',e=>{if(drawingStroke?.id===e.pointerId){e.preventDefault();paintTo(canvasPoint(e))}});
function endDrawing(e){if(drawingStroke?.id!==e.pointerId)return;drawingStroke=null;if(drawingCanvas.hasPointerCapture(e.pointerId))drawingCanvas.releasePointerCapture(e.pointerId);$('drawing-status').textContent='Drawing updated'}drawingCanvas.addEventListener('pointerup',endDrawing);drawingCanvas.addEventListener('pointercancel',endDrawing);
drawingCanvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key))return;e.preventDefault();const n=drawingSize(),cell=256/n;if(e.key===' '){rememberDrawing();drawingStroke={last:null};paintTo(drawingCursor);drawingStroke=null}else{drawingCursor.x=Math.max(0,Math.min(n-1,drawingCursor.x+(e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0)));drawingCursor.y=Math.max(0,Math.min(n-1,drawingCursor.y+(e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0)))}renderDrawing();drawingContext.strokeStyle='#fff';drawingContext.strokeRect(drawingCursor.x*cell+1,drawingCursor.y*cell+1,cell-2,cell-2);$('drawing-status').textContent=`Column ${drawingCursor.x+1}, row ${drawingCursor.y+1}`});
